def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(r for r, row in enumerate(grid) if all(v == row[0] and v != 0 for v in row))

    def components(r0, r1):
        seen = set()
        comps = []
        for r in range(r0, r1):
            for c in range(w):
                if grid[r][c] == 0 or (r, c) in seen:
                    continue
                color = grid[r][c]
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                        if r0 <= ny < r1 and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                            seen.add((ny,nx))
                            stack.append((ny,nx))
                comps.append((color, cells))
        return comps

    upper = components(0, sep)
    lower = components(sep + 1, h)
    _, target = lower[0]
    ty0 = min(r for r, c in target)
    tx0 = min(c for r, c in target)
    tx1 = max(c for r, c in target)

    def bounds(cells):
        return (min(r for r,c in cells), max(r for r,c in cells),
                min(c for r,c in cells), max(c for r,c in cells))

    best = None
    for color, cells in upper:
        y0, y1, x0, x1 = bounds(cells)
        bottom = {c - x0 for r, c in cells if r == y1}
        target_top = {c - tx0 for r, c in target if r == ty0}
        overlap = len(bottom & target_top)
        if overlap == 1:
            best = (color, cells, y0, y1, x0, x1)
            break

    if best is None:
        best = max(((color, cells, *bounds(cells)) for color, cells in upper),
                   key=lambda item: item[5])

    color, cells, y0, y1, x0, x1 = best
    out = [row[:] for row in grid[sep+1:]]
    target_y = ty0 - (sep + 1)
    dest_y = target_y - (y1 - y0 + 1)
    for r, c in cells:
        out[dest_y + r - y0][tx0 + c - x0] = color
    return out
